class Solution {
    public String decodeMessage(String key, String message) {
        char[] map = new char[26];
        boolean[] seen = new boolean[26];
        char next = 'a';

        for (int i = 0; i < key.length(); i++) {
            char c = key.charAt(i);
            if (c == ' ') {
                continue;
            }
            int index = c - 'a';
            if (!seen[index]) {
                seen[index] = true;
                map[index] = next++;
            }
        }

        StringBuilder ans = new StringBuilder(message.length());
        for (int i = 0; i < message.length(); i++) {
            char c = message.charAt(i);
            ans.append(c == ' ' ? ' ' : map[c - 'a']);
        }
        return ans.toString();
    }
}

import java.util.*;

class Solution {
    public String decodeMessage(String key, String message) {
        Map<Character, Character> map = new HashMap<>();
        char next = 'a';

        for (int i = 0; i < key.length(); i++) {
            char c = key.charAt(i);
            if (c != ' ' && !map.containsKey(c)) {
                map.put(c, next++);
            }
        }

        StringBuilder ans = new StringBuilder(message.length());
        for (int i = 0; i < message.length(); i++) {
            char c = message.charAt(i);
            ans.append(c == ' ' ? ' ' : map.get(c));
        }
        return ans.toString();
    }
}

class Solution {
    public String decodeMessage(String key, String message) {
        boolean[] seen = new boolean[26];
        StringBuilder order = new StringBuilder(26);

        for (int i = 0; i < key.length(); i++) {
            char c = key.charAt(i);
            if (c == ' ') {
                continue;
            }
            int index = c - 'a';
            if (!seen[index]) {
                seen[index] = true;
                order.append(c);
            }
        }

        StringBuilder decoded = new StringBuilder(message.length());
        for (int i = 0; i < message.length(); i++) {
            char c = message.charAt(i);
            if (c == ' ') {
                decoded.append(' ');
            } else {
                decoded.append((char) ('a' + order.indexOf(String.valueOf(c))));
            }
        }
        return decoded.toString();
    }
}

class Solution {
    public String decodeMessage(String key, String message) {
        char[] decoder = new char[128];
        decoder[' '] = ' ';
        char next = 'a';

        for (int i = 0; i < key.length(); i++) {
            char c = key.charAt(i);
            if (c != ' ' && decoder[c] == 0) {
                decoder[c] = next++;
            }
        }

        StringBuilder decoded = new StringBuilder(message.length());
        for (int i = 0; i < message.length(); i++) {
            decoded.append(decoder[message.charAt(i)]);
        }
        return decoded.toString();
    }
}
